/**
 * REPRODUCTION MATRIX — "I can't update a budget" (2026-08-10).
 * Replays the EXACT save flow EditBudgetPage performs (every editable row
 * posted, chronology defaults: effectiveFrom = first of current month,
 * completePrevious = true) across the realistic scenarios, to find which
 * one breaks. Temporary file; reproducing cases get pinned as regressions.
 */

import { describe, test, expect } from "bun:test";
import type { CreateEnvelopeResponse, EditBudgetResponse, GridResponse } from "../src/server/contract.ts";
import { currentPeriod } from "../src/platform/time.ts";
import { monthBounds, periodKey } from "../src/envelope/period.ts";
import { makeTestApp, postJson, getJson, type TestApp } from "./server-test-app.ts";

const TZ = "Australia/Melbourne";
const NOW = currentPeriod(TZ);
const FIRST = monthBounds(NOW).first; // what firstOfCurrentMonthIso() yields in the SPA
const MID = `${periodKey(NOW)}-05`;

async function createEnvelope(t: TestApp, cookie: string, body: unknown): Promise<string> {
  const res = await postJson(t.app, "/api/envelopes", body, cookie);
  expect(res.status).toBe(200);
  return ((await res.json()) as CreateEnvelopeResponse).id;
}

async function grid(t: TestApp, cookie: string): Promise<GridResponse> {
  const res = await getJson(t.app, "/api/envelopes", cookie);
  expect(res.status).toBe(200);
  return (await res.json()) as GridResponse;
}

/** The SPA's normalisePeriods/monthlyEquivalentCents round-trip, verbatim. */
const PERIODS_PER_YEAR = { weekly: 52, fortnightly: 26, monthly: 12, annual: 1 } as const;
type P = keyof typeof PERIODS_PER_YEAR;
const display = (monthlyCents: number, period: P) =>
  Math.round((monthlyCents * 12) / PERIODS_PER_YEAR[period]);
const monthlyEquivalent = (cents: number, period: P) =>
  Math.round((cents * PERIODS_PER_YEAR[period]) / 12);

/** Save exactly as the SPA does: ALL rows, chronology defaults. */
async function spaSave(
  t: TestApp,
  cookie: string,
  edits: Record<string, number>, // envelopeId -> new amount in the row's period
  opts: { effectiveFrom?: string } = {},
): Promise<Response> {
  const g = await grid(t, cookie);
  const lines = g.rows.map((r) => {
    const own = r.ownAllocationCents ?? r.allocationCents;
    const disp = edits[r.id] ?? display(own, r.period as P);
    return { envelopeId: r.id, amountCents: monthlyEquivalent(disp, r.period as P), period: r.period };
  });
  return postJson(
    t.app,
    "/api/budget/edit",
    { lines, scope: "ongoing", effectiveFrom: opts.effectiveFrom ?? FIRST, completePrevious: true },
    cookie,
  );
}

describe("repro matrix: budget update via the SPA's exact flow", () => {
  test("A: plain first edit applies", async () => {
    const t = await makeTestApp();
    const cookie = await t.signIn();
    const id = await createEnvelope(t, cookie, { name: "Groceries", type: "expense", budgetedCents: 50000, period: "monthly" });
    const res = await spaSave(t, cookie, { [id]: 60000 });
    expect(res.status).toBe(200);
    expect(((await res.json()) as EditBudgetResponse).changed).toBe(1);
    expect((await grid(t, cookie)).rows.find((r) => r.id === id)?.allocationCents).toBe(60000);
  });

  test("B: second edit in the same month applies", async () => {
    const t = await makeTestApp();
    const cookie = await t.signIn();
    const id = await createEnvelope(t, cookie, { name: "Groceries", type: "expense", budgetedCents: 50000, period: "monthly" });
    expect((await spaSave(t, cookie, { [id]: 60000 })).status).toBe(200);
    const res = await spaSave(t, cookie, { [id]: 65000 });
    expect(res.status).toBe(200);
    expect(((await res.json()) as EditBudgetResponse).changed).toBe(1);
    expect((await grid(t, cookie)).rows.find((r) => r.id === id)?.allocationCents).toBe(65000);
  });

  test("C: cleared From date (the SPA sends effectiveFrom: '')", async () => {
    const t = await makeTestApp();
    const cookie = await t.signIn();
    const id = await createEnvelope(t, cookie, { name: "Groceries", type: "expense", budgetedCents: 50000, period: "monthly" });
    const res = await spaSave(t, cookie, { [id]: 60000 }, { effectiveFrom: "" });
    // What does the server do with the SPA's cleared-field payload?
    console.log("C status:", res.status, await res.text());
    expect(res.status).toBe(200); // the user expects the save to work
  });

  test("D: untouched non-monthly row survives a save of a different row", async () => {
    const t = await makeTestApp();
    const cookie = await t.signIn();
    const weekly = await createEnvelope(t, cookie, { name: "Gym", type: "expense", budgetedCents: 2308, period: "weekly" });
    const other = await createEnvelope(t, cookie, { name: "Fuel", type: "expense", budgetedCents: 20000, period: "monthly" });
    const before = (await grid(t, cookie)).rows.find((r) => r.id === weekly)?.allocationCents;
    const res = await spaSave(t, cookie, { [other]: 25000 });
    expect(res.status).toBe(200);
    const body = (await res.json()) as EditBudgetResponse;
    console.log("D changed:", body.changed, "weekly before:", before);
    expect(body.changed).toBe(1); // ONLY the edited row should version
    expect((await grid(t, cookie)).rows.find((r) => r.id === weekly)?.allocationCents).toBe(before!);
  });

  test("E: edit after an existing mid-month version applies", async () => {
    const t = await makeTestApp();
    const cookie = await t.signIn();
    const id = await createEnvelope(t, cookie, { name: "Groceries", type: "expense", budgetedCents: 50000, period: "monthly" });
    // Nick's July pattern: a mid-month change earlier this month (prorates).
    const mid = await postJson(
      t.app,
      "/api/budget/edit",
      { lines: [{ envelopeId: id, amountCents: 60000 }], scope: "ongoing", effectiveFrom: MID, completePrevious: true },
      cookie,
    );
    expect(mid.status).toBe(200);
    const prorated = (await grid(t, cookie)).rows.find((r) => r.id === id)?.allocationCents;
    console.log("E prorated after mid-month change:", prorated);
    // Now the ordinary SPA save: bump to 700 with the default From (first of month).
    const res = await spaSave(t, cookie, { [id]: 70000 });
    expect(res.status).toBe(200);
    const after = (await grid(t, cookie)).rows.find((r) => r.id === id)?.allocationCents;
    console.log("E after save:", after);
    expect(after).toBe(70000);
  });

  test("F: untouched rows during E's save do not churn", async () => {
    const t = await makeTestApp();
    const cookie = await t.signIn();
    const id = await createEnvelope(t, cookie, { name: "Groceries", type: "expense", budgetedCents: 50000, period: "monthly" });
    const other = await createEnvelope(t, cookie, { name: "Fuel", type: "expense", budgetedCents: 20000, period: "monthly" });
    await postJson(
      t.app,
      "/api/budget/edit",
      { lines: [{ envelopeId: id, amountCents: 60000 }], scope: "ongoing", effectiveFrom: MID, completePrevious: true },
      cookie,
    );
    // SPA posts EVERY row: the prorated Groceries row goes back as a "monthly rate".
    const res = await spaSave(t, cookie, { [other]: 25000 });
    expect(res.status).toBe(200);
    const body = (await res.json()) as EditBudgetResponse;
    console.log("F changed:", body.changed);
    const after = (await grid(t, cookie)).rows.find((r) => r.id === id)?.allocationCents;
    console.log("F groceries after:", after);
    expect(body.changed).toBe(1); // only Fuel
  });
});

