if (completePrevious) {
  const cutoff = previousDay(effectiveFrom);
  for (let i = 0; i < lines.length; i++) {
    const t = lines[i]!;
    if (t.envelopeId !== line.envelopeId) continue;
    // Truncate every version whose window reaches effectiveFrom — open
